#include "marketplace.hpp"
#include "app.hpp"
#include "extensions.hpp"
namespace aether::ui{
Marketplace::Marketplace(Graphics& g,App& app):Surface(g),app_(app){if(!create(L"Aether Marketplace",WS_OVERLAPPEDWINDOW,WS_EX_APPWINDOW,{0,0,1040,760}))throw std::runtime_error("Could not create Marketplace.");accessibility_=std::make_unique<Accessibility>(hwnd_);}
Marketplace::~Marketplace(){accessibility_->detach();destroy();}
void Marketplace::refresh(){std::string error;installed_=win::installedPackages(&error);if(!error.empty())notice_=win::wide(error);invalidate();}
void Marketplace::open(const win::Monitor& monitor){setTheme(app_.theme());move(popupBounds(monitor.work,1040,760,monitor.dpi),false);refresh();show(true);SetFocus(hwnd_);}
const win::InstalledPackage* Marketplace::receipt()const{const auto& p=win::bundledCatalog()[selected_];auto found=std::find_if(installed_.begin(),installed_.end(),[&](const auto& x){return x.id==p.id;});return found==installed_.end()?nullptr:&*found;}
std::string Marketplace::widgetId()const{auto r=receipt();return r?"aether-market-"+r->id+"-"+r->receipt:std::string{};}
void Marketplace::install(){if(!visible())return;std::string error;auto p=win::installPackage(win::bundledCatalog()[selected_].id,&error);notice_=p?L"Installed locally. Select Apply / enable when ready.":win::wide(error);refresh();}
void Marketplace::apply(){if(!visible()||!receipt())return;const auto p=win::bundledCatalog()[selected_];auto config=app_.config();std::string error;bool ok=true;
 if(p.kind==win::PackageKind::Theme){config.theme=preset(p.preset);if(p.id=="aurora-look")config.theme.style=ThemeStyle::Frosted;app_.apply(config);setTheme(app_.theme());}
 else if(p.kind==win::PackageKind::Wallpaper){config.animatedWallpaper=p.preset;app_.apply(config);}
 else{auto package=p.preset?productivityExtension():sleekDeskExtension(0);package.id=widgetId();auto id=app_.extensions().install(package,&error);ok=id&&app_.extensions().setEnabled(*id,true,&error);}
 notice_=ok?(p.kind==win::PackageKind::Wallpaper?app_.liveWallpaperNotice():L"Package applied. Manage widget positions in Native extensions."):win::wide(error);invalidate();
}
void Marketplace::disable(){if(!visible()||!receipt())return;const auto p=win::bundledCatalog()[selected_];std::string error;bool ok=true;
 if(p.kind==win::PackageKind::Wallpaper){if(app_.config().animatedWallpaper==p.preset){auto config=app_.config();config.animatedWallpaper=0;app_.apply(config);}}
 else if(p.kind==win::PackageKind::Widgets){for(const auto& e:app_.extensions().library().entries())if(e.manifest.id==widgetId())ok=app_.extensions().setEnabled(e.storageId,false,&error);}
 notice_=ok?L"Package disabled. Windows static wallpaper remains unchanged.":win::wide(error);invalidate();
}
void Marketplace::remove(){if(!visible()||!receipt())return;const auto r=*receipt();const auto p=win::bundledCatalog()[selected_];std::string error;
 if(p.kind==win::PackageKind::Widgets){std::string storage;for(const auto& e:app_.extensions().library().entries())if(e.manifest.id==widgetId())storage=e.storageId;if(!storage.empty()&&!app_.extensions().remove(storage,&error)){notice_=win::wide(error);invalidate();return;}}
 if(p.kind==win::PackageKind::Wallpaper)disable();bool ok=win::removePackage(r.receipt,&error);notice_=ok?L"Package removed. Applied palette colors are retained.":win::wide(error);refresh();
}
void Marketplace::button(Canvas& c,D2D1_RECT_F r,std::wstring name,std::function<void()> action,bool enabled){c.fill(r,enabled?theme_.surface:theme_.background,8);c.text(name,r,enabled?theme_.foreground:theme_.muted,12,true,1);auto node=accessibleNode(hwnd_,static_cast<long>(actions_.size()+1),name,ROLE_SYSTEM_PUSHBUTTON,STATE_SYSTEM_FOCUSABLE|(enabled?0:STATE_SYSTEM_UNAVAILABLE),r,factor_);node.invoke=[this,enabled,action=std::move(action)]{if(visible()&&enabled)action();};node.focus=[this,index=static_cast<int>(actions_.size())]{if(visible()){focused_=index;SetFocus(hwnd_);invalidate();}};actions_.push_back(std::move(node));rects_.push_back(r);}
void Marketplace::paint(Canvas& c){RECT r{};GetClientRect(hwnd_,&r);factor_=std::clamp(std::min(r.right/scale()/940.f,r.bottom/scale()/640.f),.2f,1.f);c.setScale(factor_);auto s=c.size();c.fill(box(0,0,s.width,s.height),theme_.background);actions_.clear();rects_.clear();c.text(L"Discover your next desktop",box(28,16,s.width-56,40),theme_.foreground,25,true);c.text(L"Bundled catalog  /  Aether native packages  /  version 1.0",box(28,60,s.width-56,25),theme_.muted,12);
 const wchar_t* filters[]={L"All",L"Themes",L"Widgets",L"Animated"};for(int i=0;i<4;++i)button(c,box(28+i*120.f,101,108,34),filters[i],[this,i]{filter_=i;invalidate();});
 const auto& catalog=win::bundledCatalog();int row=0;for(int i=0;i<static_cast<int>(catalog.size());++i){const auto& p=catalog[i];if(filter_&&static_cast<int>(p.kind)!=filter_-1)continue;bool installed=std::any_of(installed_.begin(),installed_.end(),[&](const auto& x){return x.id==p.id;});auto rect=box(28,151+row*37.f,340,32);button(c,rect,win::wide(p.name)+(installed?L"  [installed]":L""),[this,i]{selected_=i;notice_.clear();invalidate();});actions_.back().description=win::wide(p.description+" Permissions: "+p.permissions);if(i==selected_)c.stroke(rect,theme_.accent,8,2);++row;}
 const auto& p=catalog[selected_];const float x=396,w=s.width-x-28;c.fill(box(x,151,w,132),theme_.raised,16);if(p.kind==win::PackageKind::Theme){auto t=preset(p.preset);c.fill(box(x+18,169,w-36,96),t.background,12);c.fill(box(x+32,182,w-64,20),t.surface,5);for(int i=0;i<5;++i)c.fill(box(x+40+i*42.f,222,28,28),i==2?t.accent:t.raised,8);}else{c.glyph(p.kind==win::PackageKind::Wallpaper?L'\uE91B':L'\uE713',box(x+16,170,w-32,94),theme_.accent,52);}
 c.text(win::wide(p.name),box(x,300,w,30),theme_.foreground,21,true);auto wrapped=[&](const std::wstring& text,float y,int size,std::uint32_t color){std::size_t start=0;const auto limit=static_cast<std::size_t>(std::max(16.f,w/(size*.54f)));for(int line=0;line<2&&start<text.size();++line){auto end=std::min(start+limit,text.size());if(end<text.size()){auto space=text.rfind(L' ',end);if(space!=text.npos&&space>start)end=space;}c.text(text.substr(start,end-start),box(x,y+line*18.f,w,18),color,size);start=end;while(start<text.size()&&text[start]==L' ')++start;}};wrapped(win::wide(p.description),341,12,theme_.muted);c.text(L"PERMISSIONS",box(x,389,w,22),theme_.muted,10,true);wrapped(win::wide(p.permissions),414,11,theme_.foreground);
 bool installed=receipt()!=nullptr;button(c,box(x,477,w/2-6,38),installed?L"Installed":L"Install package",[this]{install();},!installed);button(c,box(x+w/2+6,477,w/2-6,38),L"Apply / enable",[this]{apply();},installed);button(c,box(x,527,w/2-6,34),L"Disable",[this]{disable();},installed&&p.kind!=win::PackageKind::Theme);button(c,box(x+w/2+6,527,w/2-6,34),L"Remove package",[this]{remove();},installed);
 c.text(notice_.empty()?L"Local, data-only packages. Installation does not activate a package.":notice_,box(28,s.height-56,s.width-56,26),theme_.muted,11);c.text(L"Tab: focus   Enter: action   Escape: close",box(28,s.height-28,s.width-56,20),theme_.muted,10);if(GetFocus()==hwnd_&&focused_>=0&&focused_<static_cast<int>(rects_.size()))c.stroke(rects_[focused_],theme_.foreground,8,2);accessibility_->snapshot(L"Aether Marketplace",ROLE_SYSTEM_PANE,actions_,focused_+1,0);
}
void Marketplace::click(float x,float y){x/=factor_;y/=factor_;for(std::size_t i=0;i<rects_.size();++i)if(contains(rects_[i],x,y)){focused_=static_cast<int>(i);auto action=actions_[i].invoke;if(action)action();return;}}
LRESULT Marketplace::event(UINT m,WPARAM w,LPARAM l,bool& handled){handled=true;switch(m){case WM_GETMINMAXINFO:{auto* info=reinterpret_cast<MINMAXINFO*>(l);info->ptMinTrackSize={MulDiv(740,win::dpiFor(hwnd_),96),MulDiv(560,win::dpiFor(hwnd_),96)};return 0;}case WM_GETOBJECT:UpdateWindow(hwnd_);return accessibility_->object(w,l,handled);case WM_CLOSE:hide();return 0;case WM_KEYDOWN:if(w==VK_ESCAPE){hide();return 0;}if(w==VK_TAB){UpdateWindow(hwnd_);if(!actions_.empty())focused_=(focused_+(GetKeyState(VK_SHIFT)<0?-1:1)+static_cast<int>(actions_.size()))%static_cast<int>(actions_.size());invalidate();return 0;}if(w==VK_RETURN||w==VK_SPACE){if(focused_>=0&&focused_<static_cast<int>(actions_.size())){auto action=actions_[focused_].invoke;if(action)action();}return 0;}break;default:break;}handled=false;return 0;}
}
